import fs from "node:fs";
import path from "node:path";
import { expect, test, type Page, type Route } from "@playwright/test";

import { BOARDS } from "./boards";

/**
 * Flashcards generated by a model (#140): the quiz page's *Generate flashcards* asks for cards from a
 * topic or a note, shows them with a box each, and writes only the kept ones, at the end of the quiz,
 * once the person says so.
 *
 * `POST /__board/generate` is **mocked** in every check, for `prompt.spec.ts`'s reason: what is under
 * test is what the page does with an answer. The server's half — the quiz parser reading the reply,
 * the fix loop — is `test/generate-cards.test.ts`, with a scripted model.
 */

let folder = "";
let dir = "";
let problems: string[] = [];

test.beforeEach(({ page }, info) => {
  folder = `e2e-gencards-${info.testId}`;
  dir = path.join(BOARDS, folder);
  fs.mkdirSync(dir, { recursive: true });
  problems = [];
  page.on("console", (msg) => {
    if (msg.type() === "error" || msg.type() === "warning") problems.push(msg.text());
  });
  page.on("pageerror", (e) => problems.push(String(e)));
});

test.afterEach(() => {
  /* Only the folder this check made, and only when it knows which (`CLAUDE.md`, *Things that will bite*). */
  if (folder) fs.rmSync(dir, { recursive: true, force: true });
  folder = "";
  expect(problems, "console output").toEqual([]);
});

const quizFile = (leaf: string) => path.join(dir, `${leaf}.quiz.md`);
const read = (leaf: string) => fs.readFileSync(quizFile(leaf), "utf8");

function write(leaf: string, text: string): string {
  fs.writeFileSync(quizFile(leaf), text);
  return `${folder}/${leaf}`;
}

/* A question an author wrote by hand, with their own bullets and spacing and no id: the write must
   leave every byte of it, the missing id included. */
const QUIZ =
  "---\ntitle: Postgres\n---\n\nRevision.\n\n## Which fields decide visibility?\n\n* [x] `xmin`\n* [x]   `xmax`\n* [ ] `ctid`\n";

const card = (front: string, back: string) => ({ front, body: "", back, markdown: `## ${front} {card}\n\n> ${back}\n` });
const CARDS = [
  card("What is MVCC?", "Multi-version concurrency control."),
  card("What does VACUUM reclaim?", "The space held by dead tuples."),
  card("What is a tuple?", "A version of a row."),
];

/** Answer `/generate` with `body` at `status`, and keep what the page asked. */
async function answer(page: Page, status: number, body: unknown): Promise<Record<string, unknown>[]> {
  const asked: Record<string, unknown>[] = [];
  await page.route("**/__board/generate*", async (route: Route) => {
    asked.push(route.request().postDataJSON());
    await route.fulfill({ status, contentType: "application/json", body: JSON.stringify(body) });
  });
  return asked;
}

async function openDialog(page: Page, name: string) {
  await page.goto(`/?quiz=${name}`);
  await expect(page.locator("[data-dag-quiz-question]")).toHaveCount(1);
  await page.locator("[data-dag-quiz-generate]").click();
  const dialog = page.locator("[data-dag-flashcards] [role=dialog]");
  await expect(dialog).toBeVisible();
  return dialog;
}

test("cards from a topic are shown first, and only the kept ones are written at the end of the quiz", { tag: "@smoke" }, async ({
  page,
}) => {
  const name = write("topic", QUIZ);
  const asked = await answer(page, 200, { ok: true, cards: CARDS, problems: [], attempts: 1 });
  const dialog = await openDialog(page, name);

  await expect(dialog.locator("[data-dag-flashcards-topic]")).toBeFocused();
  await expect(dialog.locator("[data-dag-flashcards-go]")).toBeDisabled();
  await page.keyboard.type("Postgres MVCC");
  await dialog.locator("[data-dag-flashcards-count]").fill("3");
  await dialog.locator("[data-dag-flashcards-go]").click();

  await expect(dialog.locator("[data-dag-flashcards-card]")).toHaveCount(3);
  expect(asked).toHaveLength(1);
  expect(asked[0]).toMatchObject({ kind: "flashcards", prompt: "Postgres MVCC", count: 3 });
  expect(asked[0]!.source).toBeUndefined();
  await expect(dialog.locator("[data-dag-flashcards-front]").first()).toHaveText("What is MVCC?");
  await expect(dialog.locator("[data-dag-flashcards-back]").first()).toHaveText("Multi-version concurrency control.");
  /* Shown is not written. */
  expect(read("topic")).toBe(QUIZ);

  /* Drop the second; the button counts what is kept. */
  await dialog.locator("[data-dag-flashcards-card='1'] [data-dag-flashcards-keep]").uncheck();
  await expect(dialog.locator("[data-dag-flashcards-add]")).toHaveText("Add 2 flashcards");
  await dialog.locator("[data-dag-flashcards-add]").click();
  await expect(page.locator("[data-dag-flashcards]")).toHaveCount(0);

  await expect
    .poll(() => read("topic"))
    .toMatch(
      /\n## What is MVCC\? \{#q[0-9a-z]{6} card\}\n\n> Multi-version concurrency control\.\n\n## What is a tuple\? \{#q[0-9a-z]{6} card\}\n\n> A version of a row\.\n$/,
    );
  /* Every byte that was there is still there, the hand-written question's missing id included. */
  expect(read("topic").startsWith(QUIZ)).toBe(true);
  expect(read("topic")).not.toContain("VACUUM");
  await expect(page.locator("[data-dag-quiz-question]")).toHaveCount(3);
  await expect(page.locator("[data-dag-quiz-question]").nth(2)).toHaveAttribute("data-dag-quiz-kind", "card");
});

test("cards from a note send the note's text without its frontmatter, and what to focus on", async ({ page }) => {
  fs.writeFileSync(
    path.join(dir, "source.note.md"),
    "---\ntitle: Postgres notes\n---\n\n# MVCC\n\nEach transaction reads a snapshot.\n",
  );
  const name = write("note", QUIZ);
  const asked = await answer(page, 200, { ok: true, cards: CARDS.slice(0, 1), problems: [], attempts: 1 });
  const dialog = await openDialog(page, name);

  await dialog.locator("[data-dag-flashcards-from=note]").check();
  const pick = dialog.locator("[data-dag-flashcards-note]");
  await expect(pick.locator(`option[value="${folder}/source"]`)).toHaveText(`Postgres notes — ${folder}/source`);
  await pick.selectOption(`${folder}/source`);
  /* A note is enough on its own: what to focus on is optional. */
  await expect(dialog.locator("[data-dag-flashcards-go]")).toBeEnabled();
  await dialog.locator("[data-dag-flashcards-topic]").fill("only the definitions");
  await dialog.locator("[data-dag-flashcards-go]").click();

  await expect(dialog.locator("[data-dag-flashcards-card]")).toHaveCount(1);
  expect(asked[0]).toMatchObject({
    kind: "flashcards",
    prompt: "only the definitions",
    source: "# MVCC\n\nEach transaction reads a snapshot.",
    count: 10,
  });
  await expect(dialog.locator("[data-dag-flashcards-add]")).toHaveText("Add 1 flashcard");
  await dialog.locator("[data-dag-flashcards-add]").click();
  await expect
    .poll(() => read("note"))
    .toMatch(/\n## What is MVCC\? \{#q[0-9a-z]{6} card\}\n\n> Multi-version concurrency control\.\n$/);
});

test("an answer with no card, or a refusal, says why and writes nothing", async ({ page }) => {
  const name = write("refused", QUIZ);
  const why = "The model answered without a single flashcard: “I can't help with that.”";
  await answer(page, 200, { ok: false, cards: [], problems: [], attempts: 3, error: why });
  const dialog = await openDialog(page, name);
  await dialog.locator("[data-dag-flashcards-topic]").fill("anything");
  await dialog.locator("[data-dag-flashcards-go]").click();
  await expect(dialog.locator("[data-dag-flashcards-error]")).toHaveText(why);
  /* Still the form, with what was typed, to try again. */
  await expect(dialog.locator("[data-dag-flashcards-topic]")).toHaveValue("anything");
  await expect(dialog.locator("[data-dag-flashcards-card]")).toHaveCount(0);

  /* A refusal of the request itself — no model set up — is said the same way. */
  await page.unroute("**/__board/generate*");
  await answer(page, 400, { error: "no model is set up: choose one in Settings → AI and agents" });
  await dialog.locator("[data-dag-flashcards-go]").click();
  await expect(dialog.locator("[data-dag-flashcards-error]")).toHaveText(
    "no model is set up: choose one in Settings → AI and agents",
  );

  /* A 400 is a console error in Chromium's own words; it is the answer this check is about. */
  problems = problems.filter((p) => !p.includes("400"));

  await page.keyboard.press("Escape");
  await expect(page.locator("[data-dag-flashcards]")).toHaveCount(0);
  expect(read("refused")).toBe(QUIZ);
});

test("cards left out are counted, and closing the list writes nothing", async ({ page }) => {
  const name = write("closed", QUIZ);
  await answer(page, 200, {
    ok: true,
    cards: CARDS.slice(0, 2),
    problems: [{ card: 3, front: "What is WAL?", code: "EQ_NO_OPTIONS", message: "no back" }],
    attempts: 3,
  });
  const dialog = await openDialog(page, name);
  await dialog.locator("[data-dag-flashcards-topic]").fill("Postgres");
  await dialog.locator("[data-dag-flashcards-go]").click();
  await expect(dialog.locator("[data-dag-flashcards-card]")).toHaveCount(2);
  await expect(dialog.locator("[data-dag-flashcards-left-out]")).toHaveText(
    "1 card the model wrote could not be read as a flashcard and is not shown.",
  );
  /* Nothing kept is nothing to add. */
  for (const box of await dialog.locator("[data-dag-flashcards-keep]").all()) await box.uncheck();
  await expect(dialog.locator("[data-dag-flashcards-add]")).toBeDisabled();
  await dialog.locator("[data-dag-flashcards-close]").click();
  await expect(page.locator("[data-dag-flashcards]")).toHaveCount(0);
  expect(read("closed")).toBe(QUIZ);
});
